CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) UNIQUE NOT NULL,password_hash VARCHAR(100) NOT NULL,xp INT NOT NULL DEFAULT 0,streak INT NOT NULL DEFAULT 0,best_streak INT NOT NULL DEFAULT 0,last_active_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courses(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200) NOT NULL,prompt TEXT,pinned TINYINT(1) NOT NULL DEFAULT 0,pinned_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lessons(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,unit_idx INT NOT NULL,unit_title VARCHAR(200),title VARCHAR(200) NOT NULL,content LONGTEXT NULL,completed_at DATETIME NULL,score INT NULL,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS answers(id INT AUTO_INCREMENT PRIMARY KEY,lesson_id INT NOT NULL,quiz_idx INT NOT NULL,chosen INT NOT NULL,is_correct TINYINT NOT NULL,answered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(lesson_id,quiz_idx),FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS xp_events(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,lesson_id INT NULL,reason VARCHAR(30) NOT NULL,points INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tutor_messages(
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  lesson_id INT NOT NULL,
  block_idx INT NOT NULL,
  role VARCHAR(10) NOT NULL,
  content TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX(lesson_id,user_id),
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE
);
